const cfg = {
  site_id: "tx001",
  site_name: "Site Name",
  site_city: "City",
  site_lat: 44.7866,
  site_lon: 20.4489,

  gateway_ip: "10.13.0.1",
  pc_ip: "10.13.0.10",
  transmitter_ip: "10.13.0.50",
  modbus_ip: "10.13.0.150",

  ping_cmd_template: "ping -n 1 ${ip}",

  snmp: {
    community: "public",
    host: "10.13.0.50",
    oids_fast: {
      reflection: "1.3.6.1.4.1.35305.1.1.2.6.0",
      deviation: "1.3.6.1.4.1.35305.1.1.2.7.0",
      tx_alarm: "1.3.6.1.4.1.35305.1.1.1.6.0",
      fault_alarm: "1.3.6.1.4.1.35305.1.1.1.7.0"
    },
    oids_slow: {
      temperature: "1.3.6.1.4.1.35305.1.1.2.12.0",
      power_fwd: "1.3.6.1.4.1.35305.1.1.2.5.0",
      frequency: "1.3.6.1.4.1.35305.1.1.2.3.0"
    }
  },

  modbus: {
    status_hex: "0101000000083DCC",
    base_url: "http://10.13.0.150:8000/?data="
  }
};

flow.set('site_cfg', cfg);
msg.payload = { ok: true, site_id: cfg.site_id, site_name: cfg.site_name };
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;
const o = cfg.snmp.oids_fast;
const cmd = `snmpget -v2c -c ${cfg.snmp.community} -Oqv ${cfg.snmp.host} ${o.reflection} ${o.deviation} ${o.tx_alarm} ${o.fault_alarm}`;
msg.command = cmd;
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;

const lines = String(msg.payload || '').trim().split(/\r?\n/).map(s => s.trim()).filter(Boolean);
if (lines.length < 4) return null;

const toNum = (v) => {
  const n = Number(String(v).replace(/[^0-9+-.]/g, ''));
  return Number.isFinite(n) ? n : null;
};

const reflection = toNum(lines[0]);
const deviation = toNum(lines[1]);
const tx_alarm = toNum(lines[2]);
const fault_alarm = toNum(lines[3]);

msg.payload = [
  {
    measurement: 'tx_telemetry_fast',
    tags: {
      site_id: cfg.site_id,
      site_name: cfg.site_name,
      site_city: cfg.site_city,
      site_lat: String(cfg.site_lat),
      site_lon: String(cfg.site_lon),
      device: 'transmitter',
      source: 'snmp_poll_fast'
    },
    fields: {
      reflection: reflection,
      deviation: deviation,
      tx_alarm: tx_alarm,
      fault_alarm: fault_alarm
    },
    timestamp: new Date().toISOString()
  }
];
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;
const o = cfg.snmp.oids_slow;
const cmd = `snmpget -v2c -c ${cfg.snmp.community} -Oqv ${cfg.snmp.host} ${o.temperature} ${o.power_fwd} ${o.frequency}`;
msg.command = cmd;
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;

const lines = String(msg.payload || '').trim().split(/\r?\n/).map(s => s.trim()).filter(Boolean);
if (lines.length < 3) return null;

const toNum = (v) => {
  const n = Number(String(v).replace(/[^0-9+-.]/g, ''));
  return Number.isFinite(n) ? n : null;
};

const temperature = toNum(lines[0]);
const power_fwd = toNum(lines[1]);
const frequency = toNum(lines[2]);

msg.payload = [
  {
    measurement: 'tx_telemetry_slow',
    tags: {
      site_id: cfg.site_id,
      site_name: cfg.site_name,
      site_city: cfg.site_city,
      site_lat: String(cfg.site_lat),
      site_lon: String(cfg.site_lon),
      device: 'transmitter',
      source: 'snmp_poll_slow'
    },
    fields: {
      temperature: temperature,
      power_fwd: power_fwd,
      frequency: frequency
    },
    timestamp: new Date().toISOString()
  }
];
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;

const targets = [
  { name: 'gateway', ip: cfg.gateway_ip },
  { name: 'pc', ip: cfg.pc_ip },
  { name: 'transmitter', ip: cfg.transmitter_ip },
  { name: 'modbus', ip: cfg.modbus_ip }
];

const out = [];
for (const t of targets) {
  const cmd = cfg.ping_cmd_template.replace('${ip}', t.ip);
  out.push({ payload: cmd, target: t.name, ip: t.ip });
}
return [out];

const cfg = flow.get('site_cfg');
if (!cfg) return null;

const raw = String(msg.payload || '');
const target = msg.target || 'unknown';
const ip = msg.ip || '';

const hasReply = /TTL=|ttl=|Reply from|bytes from/i.test(raw);
let rtt = null;

let m = raw.match(/Average = (\d+)ms/i);
if (m) rtt = Number(m[1]);
if (rtt === null) {
  m = raw.match(/time[=<]\s*(\d+(?:\.\d+)?)\s*ms/i);
  if (m) rtt = Number(m[1]);
}

msg.payload = [
  {
    measurement: 'site_ping_health',
    tags: {
      site_id: cfg.site_id,
      site_name: cfg.site_name,
      site_city: cfg.site_city,
      site_lat: String(cfg.site_lat),
      site_lon: String(cfg.site_lon),
      device: target,
      source: 'ping'
    },
    fields: {
      up: hasReply ? 1 : 0,
      rtt_ms: rtt === null ? -1 : rtt,
      target_ip: ip
    },
    timestamp: new Date().toISOString()
  }
];
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;
msg.method = 'GET';
msg.url = cfg.modbus.base_url + cfg.modbus.status_hex;
msg._modbusReadTs = Date.now();
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;

const b = msg.payload;
if (!Buffer.isBuffer(b) || b.length < 4) return null;

const statusByte = b[3];
const fields = {};
for (let i = 0; i < 8; i++) {
  fields[`relay_${i+1}`] = (statusByte & (1 << i)) ? 1 : 0;
}
fields.reachable = 1;
fields.rtt_ms = Date.now() - (msg._modbusReadTs || Date.now());

msg.payload = [
  {
    measurement: 'relay_status',
    tags: {
      site_id: cfg.site_id,
      site_name: cfg.site_name,
      site_city: cfg.site_city,
      site_lat: String(cfg.site_lat),
      site_lon: String(cfg.site_lon),
      device: 'waveshare_relay',
      source: 'modbus_poll'
    },
    fields: fields,
    timestamp: new Date().toISOString()
  }
];
return msg;

const cfg = flow.get('site_cfg');
if (!cfg) return null;

const p = msg.payload || {};
const channel = Number(p.channel);
const state = Number(p.state);
if (!Number.isInteger(channel) || channel < 1 || channel > 8) {
  if (msg.res) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'channel must be 1..8' };
    return [null, msg, null];
  }
  return null;
}
if (!(state === 0 || state === 1)) {
  if (msg.res) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: 'state must be 0 or 1' };
    return [null, msg, null];
  }
  return null;
}

const command_id = `${cfg.site_id}-${Date.now()}-${Math.floor(Math.random() * 100000)}`;
msg._relayCmd = {
  command_id,
  channel,
  target_state: state,
  source: p.source || 'api',
  retry_count: Number(p.retry_count || 0),
  ts_send_iso: new Date().toISOString()
};

const queueMsg = RED.util.cloneMessage(msg);
const ackMsg = msg.res ? RED.util.cloneMessage(msg) : null;
const logMsg = RED.util.cloneMessage(msg);

if (ackMsg) {
  ackMsg.statusCode = 202;
  ackMsg.payload = {
    ok: true,
    accepted: true,
    command_id: msg._relayCmd.command_id,
    channel: msg._relayCmd.channel,
    target_state: msg._relayCmd.target_state
  };
}

logMsg.payload = [{
  measurement: 'relay_command',
  tags: {
    site_id: cfg.site_id,
    site_name: cfg.site_name,
    site_city: cfg.site_city,
    site_lat: String(cfg.site_lat),
    site_lon: String(cfg.site_lon),
    device: 'waveshare_relay',
    source: msg._relayCmd.source
  },
  fields: {
    command_id: msg._relayCmd.command_id,
    channel: msg._relayCmd.channel,
    target_state: msg._relayCmd.target_state,
    retry_count: msg._relayCmd.retry_count
  },
  timestamp: msg._relayCmd.ts_send_iso
}];

return [queueMsg, ackMsg, logMsg];

const cfg = flow.get('site_cfg');
if (!cfg || !msg._relayCmd) return null;

const cmdOn = [
  '01050000FF008C3A',
  '010500015500A35A',
  '010500025500535A',
  '010500035500029A',
  '010500045500B35B',
  '010500055500E29B',
  '010500065500129B',
  '010500075500435B'
];
const cmdOff = [
  '010500000000CDCA',
  '010500015500A35A',
  '010500025500535A',
  '010500035500029A',
  '010500045500B35B',
  '010500055500E29B',
  '010500065500129B',
  '010500075500435B'
];

const idx = msg._relayCmd.channel - 1;
const hex = msg._relayCmd.target_state === 1 ? cmdOn[idx] : cmdOff[idx];
if (!hex) return null;

msg.method = 'GET';
msg.url = cfg.modbus.base_url + hex;
msg._relayCmd.command_hex = hex;
msg._relayCmd.exec_ts_ms = Date.now();
return msg;

if (!msg._relayCmd) return null;
msg._relayCmd.command_rtt_ms = Date.now() - (msg._relayCmd.exec_ts_ms || Date.now());
msg._relayCmd.cmd_resp_hex = Buffer.isBuffer(msg.payload) ? msg.payload.toString('hex').toUpperCase() : String(msg.payload || '');
msg.delay = 700;
return msg;

const cfg = flow.get('site_cfg');
if (!cfg || !msg._relayCmd) return null;
msg.method = 'GET';
msg.url = cfg.modbus.base_url + cfg.modbus.status_hex;
msg._relayCmd.verify_ts_ms = Date.now();
return msg;

if (!msg._relayCmd) return null;

const b = msg.payload;
if (!Buffer.isBuffer(b) || b.length < 4) {
  msg._relayCmd.verify_error = 'Invalid status response';
  return [null, msg];
}

const statusByte = b[3];
const bit = msg._relayCmd.channel - 1;
const actual = (statusByte & (1 << bit)) ? 1 : 0;
msg._relayCmd.actual_state = actual;
msg._relayCmd.verify_rtt_ms = Date.now() - (msg._relayCmd.verify_ts_ms || Date.now());
msg._relayCmd.ack_ok = actual === msg._relayCmd.target_state;

if (msg._relayCmd.ack_ok) return [msg, null];
return [null, msg];

if (!msg._relayCmd) return null;
const maxRetries = 2;
const cur = Number(msg._relayCmd.retry_count || 0);
if (cur < maxRetries) {
  msg._relayCmd.retry_count = cur + 1;
  return [msg, null];
}
return [null, msg];

const cfg = flow.get('site_cfg');
if (!cfg || !msg._relayCmd) return null;

msg.payload = [{
  measurement: 'relay_ack',
  tags: {
    site_id: cfg.site_id,
    site_name: cfg.site_name,
    site_city: cfg.site_city,
    site_lat: String(cfg.site_lat),
    site_lon: String(cfg.site_lon),
    device: 'waveshare_relay',
    source: msg._relayCmd.source
  },
  fields: {
    command_id: msg._relayCmd.command_id,
    channel: msg._relayCmd.channel,
    target_state: msg._relayCmd.target_state,
    actual_state: msg._relayCmd.actual_state,
    ack_ok: 1,
    retry_count: msg._relayCmd.retry_count || 0,
    command_rtt_ms: msg._relayCmd.command_rtt_ms || -1,
    verify_rtt_ms: msg._relayCmd.verify_rtt_ms || -1
  },
  timestamp: new Date().toISOString()
}];
return msg;

const cfg = flow.get('site_cfg');
if (!cfg || !msg._relayCmd) return null;

msg.payload = [{
  measurement: 'relay_ack',
  tags: {
    site_id: cfg.site_id,
    site_name: cfg.site_name,
    site_city: cfg.site_city,
    site_lat: String(cfg.site_lat),
    site_lon: String(cfg.site_lon),
    device: 'waveshare_relay',
    source: msg._relayCmd.source
  },
  fields: {
    command_id: msg._relayCmd.command_id,
    channel: msg._relayCmd.channel,
    target_state: msg._relayCmd.target_state,
    actual_state: (msg._relayCmd.actual_state ?? -1),
    ack_ok: 0,
    retry_count: msg._relayCmd.retry_count || 0,
    command_rtt_ms: msg._relayCmd.command_rtt_ms || -1,
    verify_rtt_ms: msg._relayCmd.verify_rtt_ms || -1,
    error: msg._relayCmd.verify_error || 'Verify mismatch'
  },
  timestamp: new Date().toISOString()
}];
return msg;
